package main

func (a *app) migrate() error {
	statements := []string{
		`CREATE TABLE IF NOT EXISTS users (id BIGINT PRIMARY KEY AUTO_INCREMENT,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARBINARY(255) NOT NULL,plan VARCHAR(12) NOT NULL DEFAULT 'free',pro_until DATETIME NULL,stripe_customer_id VARCHAR(100) NULL UNIQUE,stripe_subscription_id VARCHAR(100) NULL UNIQUE,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP)`,
		`CREATE TABLE IF NOT EXISTS sessions (token_hash BINARY(32) PRIMARY KEY,user_id BIGINT NOT NULL,expires_at DATETIME NOT NULL,INDEX (user_id),FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE)`,
		`CREATE TABLE IF NOT EXISTS password_resets (token_hash BINARY(32) PRIMARY KEY,user_id BIGINT NOT NULL,expires_at DATETIME NOT NULL,used_at DATETIME NULL,INDEX(user_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE)`,
		`CREATE TABLE IF NOT EXISTS projects (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,scene_id VARCHAR(80) NOT NULL,name VARCHAR(100) NOT NULL,config JSON NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(user_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE)`,
		`CREATE TABLE IF NOT EXISTS favorites (user_id BIGINT NOT NULL,scene_id VARCHAR(80) NOT NULL,PRIMARY KEY(user_id,scene_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE)`,
		`CREATE TABLE IF NOT EXISTS exports (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,month_key CHAR(7) NOT NULL,status VARCHAR(12) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,month_key,status),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE)`,
		`CREATE TABLE IF NOT EXISTS stripe_events (id VARCHAR(100) PRIMARY KEY,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP)`,
	}
	for _, q := range statements {
		if _, err := a.db.Exec(q); err != nil {
			return err
		}
	}
	return nil
}
